def _schema_name(report_filename: str) -> str:
    stem = report_filename.removesuffix(".report.json").replace("PR165_D3_", "pr165_d3_")
    stem = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1_\2", stem)
    stem = re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", stem)
    return stem.replace("__", "_").lower() + ".schema.json"
